// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.*;

import java.util.concurrent.atomic.AtomicBoolean;
import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelQueryCancelledException;
import org.junit.jupiter.api.Test;

class NativeSegmentedCancellationTest {
	@Test
	void collisionSearchObservesCancellationRaisedAfterHashing() {
		var manager = LmdbQueryMemoryManager.createForTesting(200_000, 200_000);
		var interrupt = new AtomicBoolean();
		try (var ledger = manager.openQuery(); var table = new NativeSegmentedTupleTable(1, ledger, 1024, h -> {
			if (interrupt.get()) Thread.currentThread().interrupt();
			return 1;
		})) {
			for (int i=0;i<100;i++) assertEquals(1,table.add(new long[] { i}));
			interrupt.set(true);
			try { assertThrows(KernelQueryCancelledException.class, () -> table.add(new long[] { 100})); }
			finally { Thread.interrupted(); }
			assertEquals(100, table.size);
		}
		assertEquals(0,manager.usedBytes());
	}
	@Test
	void bucketRehashObservesCancellationAndCloseReleasesPeakClaim() throws Exception {
		var manager = LmdbQueryMemoryManager.createForTesting(200_000, 200_000);
		var nextHash = new java.util.concurrent.atomic.AtomicInteger();
		try (var ledger = manager.openQuery(); var table = new NativeSegmentedTupleTable(1, ledger, 1024, h -> {
			int hash = nextHash.getAndIncrement();
			if (hash == 384) Thread.currentThread().interrupt();
			return hash;
		})) {
			for (int i=0;i<384;i++) assertEquals(1,table.add(new long[] { i}));
			// Hash 384 targets an empty bucket: lookup performs no collision-loop poll. This add
			// crosses the 75% threshold, so cancellation must be observed inside the rehash loop.
			try { assertThrows(KernelQueryCancelledException.class, () -> table.add(new long[] { 384})); }
			finally { Thread.interrupted(); }
			assertEquals(384,table.size);
		}
		assertEquals(0,manager.usedBytes());
	}
}
